mapper.select:
/* DailyContractMapper.selectSignId */
SELECT CONCAT('CS', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_CONTRACT_SIGN'))
FROM DUAL

/* DailyContractMapper.selectContractByVer */
SELECT
    SITE_CD                                       AS siteCd
    , CONTRACT_VER                                AS contractVer
    , CONTRACT_NM                                 AS contractNm
    , FILE_MGMT_CD                                AS fileMgmtCd
    , DATE_FORMAT(INSERT_DATE, '%Y-%m-%d %H:%i')  AS insertDate
FROM TB_DAILY_CONTRACT
WHERE CMPNY_CD     = #{cmpnyCd}
  AND SITE_CD      = #{siteCd}
  AND CONTRACT_VER = #{contractVer}

/* DailyContractMapper.selectNextContractVer */
SELECT IFNULL(MAX(CONTRACT_VER), 0) + 1
FROM TB_DAILY_CONTRACT
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}

mapper.update:
/* DailyContractMapper.updateContractDeactivate */
UPDATE TB_DAILY_CONTRACT
SET USE_YN        = 'N'
    , UPDATE_NO   = #{updateNo}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}
  AND USE_YN   = 'Y'

mapper.insert:
/* DailyContractMapper.insertContract */
INSERT INTO TB_DAILY_CONTRACT (
    CMPNY_CD
    , SITE_CD
    , CONTRACT_VER
    , CONTRACT_NM
    , FILE_MGMT_CD
    , USE_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{cmpnyCd}
    , #{siteCd}
    , #{contractVer}
    , #{contractNm}
    , #{fileMgmtCd}
    , 'Y'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* DailyContractMapper.selectContractFileMgmtCd */
SELECT FILE_MGMT_CD
FROM TB_DAILY_CONTRACT
WHERE CMPNY_CD     = #{cmpnyCd}
  AND SITE_CD      = #{siteCd}
  AND CONTRACT_VER = #{contractVer}

/* DailyContractMapper.selectDailyUserMeta */
SELECT
    SITE_CD     AS siteCd
    , USER_NM   AS userNm
FROM TB_DAILY_USER
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}

mapper.insert:
/* DailyContractMapper.insertContractSign */
INSERT INTO TB_DAILY_CONTRACT_SIGN (
    CMPNY_CD
    , SIGN_ID
    , SITE_CD
    , USER_CD
    , USER_NM_SNAPSHOT
    , CONTRACT_VER
    , REQ_ID
    , SIGN_FILE_MGMT_CD
    , MERGED_FILE_MGMT_CD
    , MERGED_SHA256
    , FIRST_WORK_DATE
    , SIGN_DTIME
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{cmpnyCd}
    , #{signId}
    , #{siteCd}
    , #{userCd}
    , #{userNmSnapshot}
    , #{contractVer}
    , #{reqId}
    , #{signFileMgmtCd}
    , #{mergedFileMgmtCd}
    , #{mergedSha256}
    , #{firstWorkDate}
    , NOW()
    , #{userCd}
    , NOW()
)

mapper.select:
/* DailyContractMapper.selectSignListForAdmin */ SELECT S.SIGN_ID AS signId , S.SITE_CD AS siteCd , S.USER_CD AS userCd , S.USER_NM_SNAPSHOT AS userNmSnapshot , D.MBL_NO_LAST4 AS mblNoLast4 , D.MBL_NO_ENC AS mblNoEnc , S.CONTRACT_VER AS contractVer , S.FIRST_WORK_DATE AS firstWorkDate , DATE_FORMAT(S.SIGN_DTIME, '%Y-%m-%d %H:%i') AS signDtime , S.MERGED_SHA256 AS mergedSha256 FROM TB_DAILY_CONTRACT_SIGN S LEFT JOIN TB_DAILY_USER D ON ( S.CMPNY_CD = D.CMPNY_CD AND S.USER_CD = D.USER_CD ) WHERE S.CMPNY_CD = #{cmpnyCd} AND S.SITE_CD = #{siteCd}
AND S.SIGN_DTIME >= STR_TO_DATE(#{fromDate}, '%Y%m%d')
AND S.SIGN_DTIME < DATE_ADD(STR_TO_DATE(#{toDate}, '%Y%m%d'), INTERVAL 1 DAY)
AND S.USER_NM_SNAPSHOT LIKE CONCAT('%', #{userNm}, '%')
ORDER BY S.SIGN_DTIME DESC LIMIT #{limitCnt}

/* DailyContractMapper.selectSignCntByVer */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_CONTRACT_SIGN
     WHERE CMPNY_CD     = #{cmpnyCd}
       AND SITE_CD      = #{siteCd}
       AND CONTRACT_VER = #{contractVer}
     LIMIT 1
) T

/* DailyContractMapper.selectContractForUpdate */
SELECT
    CONTRACT_VER                                    AS contractVer
    , CONTRACT_NM                                   AS contractNm
    , FILE_MGMT_CD                                  AS fileMgmtCd
    , USE_YN                                        AS useYn
FROM TB_DAILY_CONTRACT
WHERE CMPNY_CD     = #{cmpnyCd}
  AND SITE_CD      = #{siteCd}
  AND CONTRACT_VER = #{contractVer}
FOR UPDATE

mapper.update:
/* DailyContractMapper.updateContractFile */
UPDATE TB_DAILY_CONTRACT
SET FILE_MGMT_CD  = #{fileMgmtCd}
    , UPDATE_NO   = #{updateNo}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD     = #{cmpnyCd}
  AND SITE_CD      = #{siteCd}
  AND CONTRACT_VER = #{contractVer}
  AND USE_YN       = 'Y'

mapper.select:
/* DailyContractMapper.selectPinnedApprovedReqCnt */
SELECT COUNT(*)
FROM TB_DAILY_ENTRY_REQUEST
WHERE CMPNY_CD     = #{cmpnyCd}
  AND SITE_CD      = #{siteCd}
  AND REQ_STATUS   IN ('02', '05')
  AND CONTRACT_VER = #{contractVer}
  AND  (PROC_DTIME >= CURDATE() OR CONSUME_DTIME >= CURDATE())

/* DailyContractMapper.selectPendingReqCnt */
SELECT COUNT(*)
FROM TB_DAILY_ENTRY_REQUEST
WHERE CMPNY_CD   = #{cmpnyCd}
  AND SITE_CD    = #{siteCd}
  AND REQ_STATUS = '01'
